package nameparse

import (
	"encoding/json"
	"os"
	"testing"
)

// testdata/lastfirst.json holds what upstream's nameToLastFirst
// (server/utils/parsers/parseNameString.js) returns for each key, generated by
// running the pinned JavaScript over the key list.
func TestToLastFirstMatchesUpstream(t *testing.T) {
	raw, err := os.ReadFile("testdata/lastfirst.json")
	if err != nil {
		t.Fatal(err)
	}
	var golden map[string]string
	if err := json.Unmarshal(raw, &golden); err != nil {
		t.Fatal(err)
	}
	if len(golden) < 40 {
		t.Fatalf("golden has only %d names", len(golden))
	}
	for name, want := range golden {
		if got := ToLastFirst(name); got != want {
			t.Errorf("ToLastFirst(%q) = %q, upstream %q", name, got, want)
		}
	}
}
